"use client";

import { useId, useLayoutEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { cn } from "cn";
import "@fontsource/inter/latin-400.css";
import "@fontsource/inter/latin-500.css";
import { BreakdownPicker } from "@/components/ui/kalos-breakdown-picker";
import { BreakdownPlot, type BreakdownRow } from "@/components/ui/kalos-breakdown-plot";
import { breakdownChartCss, breakdownChartStyleHref, breakdownPalette } from "@/components/ui/kalos-breakdown-chart-styles";

export type BreakdownRecord = Record<string, unknown>;

export interface Dimension {
  key: string;
  label: string;
  values: readonly string[];
  colors?: Readonly<Record<string, string>>;
  icons?: Readonly<Record<string, ReactNode>>;
}

export interface Measure {
  key: string;
  label: string;
  unit: string;
  field?: string;
}

export interface KalosBreakdownChartProps {
  records: readonly BreakdownRecord[];
  dimensions: readonly Dimension[];
  measures: readonly Measure[];
  title?: string;
  defaultMeasure?: string;
  defaultSlice?: string;
  defaultSegment?: string;
  className?: string;
}

const noSegment = { key: "none", label: "None" };
const format = new Intl.NumberFormat("en-US", { maximumFractionDigits: 2 });

function groupRecords(records: readonly BreakdownRecord[], measure: Measure | undefined, slice: Dimension | undefined, segment: Dimension | undefined) {
  if (!measure || !slice) return [];
  const labels = slice.values;
  const groupIndex = new Map(labels.map((label, i) => [label, i]));
  const seriesIndex = new Map(segment?.values.map((label, i) => [label, i]));
  const groups = labels.map(label => ({
    label, values: Array<number>(segment ? segment.values.length : 1).fill(0),
  }));
  for (const record of records) {
    const row = groupIndex.get(String(record[slice.key]));
    const column = segment ? seriesIndex.get(String(record[segment.key])) : 0;
    if (row === undefined || column === undefined) continue;
    const amount = measure.field === undefined ? 1 : record[measure.field];
    if (typeof amount === "number" && Number.isFinite(amount)) groups[row].values[column] += amount;
  }
  return groups;
}

export function KalosBreakdownChart({
  records, dimensions, measures, title = "Workload", defaultMeasure, defaultSlice, defaultSegment, className,
}: KalosBreakdownChartProps) {
  const headingId = useId();
  const tableFrame = useRef<HTMLDivElement>(null);
  const tableScroll = useRef<HTMLDivElement>(null);
  useLayoutEffect(() => {
    const frame = tableFrame.current;
    const content = tableScroll.current;
    if (!frame || !content) return;
    const measureHeight = () => { frame.style.height = content.offsetHeight + "px"; };
    measureHeight();
    const resize = new ResizeObserver(measureHeight);
    resize.observe(content);
    return () => resize.disconnect();
  }, []);
  const [measureKey, setMeasureKey] = useState(defaultMeasure);
  const [sliceKey, setSliceKey] = useState(defaultSlice);
  const [segmentKey, setSegmentKey] = useState(defaultSegment);
  const [excluded, setExcluded] = useState<ReadonlySet<string>>(() => new Set());
  const [active, setActive] = useState<string | null>(null);
  const measure = measures.find(item => item.key === measureKey) ?? measures[0];
  const slice = dimensions.find(item => item.key === sliceKey) ?? dimensions[0];
  const otherDimensions = dimensions.filter(item => item.key !== slice?.key);
  const segment = dimensions.find(item => item.key !== slice?.key && item.key !== noSegment.key
    && (segmentKey === undefined || item.key === segmentKey));
  const series = useMemo(() => segment ? segment.values.map((label, index) => ({
    label, color: segment.colors?.[label] ?? breakdownPalette[index % breakdownPalette.length],
  })) : [{ label: measure?.label ?? "", color: breakdownPalette[0] }], [segment, measure]);
  const groups = useMemo(() => groupRecords(records, measure, slice, segment), [records, measure, slice, segment]);
  const hidden = useMemo(() => {
    const keys = new Set(series.filter(item => segment && excluded.has(item.label)).map(item => item.label));
    if (keys.size === series.length) keys.clear();
    return keys;
  }, [series, segment, excluded]);
  const rows: BreakdownRow[] = useMemo(() => groups.map(row => ({
    ...row, total: row.values.reduce((sum, value, index) => sum + (hidden.has(series[index].label) ? 0 : value), 0),
  })), [groups, hidden, series]);
  const total = rows.reduce((sum, row) => sum + row.total, 0);

  function changeSlice(next: string) {
    setSliceKey(next);
    // Keep the existing breakdown unless it has become the horizontal axis.
    if (next === segment?.key) {
      setSegmentKey(noSegment.key);
      setExcluded(new Set());
    } else {
      setSegmentKey(segment?.key ?? noSegment.key);
    }
    setActive(null);
  }

  function toggleSeries(label: string) {
    if (!hidden.has(label) && series.length - hidden.size <= 1) return;
    const next = new Set(hidden);
    if (next.has(label)) next.delete(label);
    else next.add(label);
    setExcluded(next);
    setActive(null);
  }

  return <section className={cn("kalos-breakdown-chart", className)} data-slot="breakdown-chart" aria-labelledby={headingId}>
    <style href={breakdownChartStyleHref} precedence="kalos-component">{breakdownChartCss}</style>
    <header className="kbc-head">
      <h3 id={headingId} className="kbc-title" title={title}>{title}</h3>
      <span className="kbc-total" aria-live="polite" aria-atomic="true"><strong>{format.format(total)}</strong> {measure?.unit}</span>
    </header>
    <div className="kbc-controls">
      <BreakdownPicker label="Measure" value={measure?.key ?? ""} options={measures} onChange={next => { setMeasureKey(next); setActive(null); }} />
      <BreakdownPicker label="Slice" value={slice?.key ?? ""} options={dimensions} onChange={changeSlice} />
      <BreakdownPicker label="Segment" value={segment?.key ?? noSegment.key} options={[noSegment, ...otherDimensions]} onChange={next => {
        setSegmentKey(next);
        setExcluded(new Set());
        setActive(null);
      }} />
    </div>
    {slice && measure && <BreakdownPlot rows={rows} series={series} slice={slice} isSegmented={!!segment} hidden={hidden}
      unit={measure.unit} active={active} onInspect={setActive} />}
    <div className="kbc-table-frame" ref={tableFrame}>
      <div className="kbc-table-scroll" ref={tableScroll}>
        <table aria-label={title} className="kbc-table">
          <thead><tr>
            <th scope="col">{slice?.label}</th>
            <th scope="col">{measure?.label}</th>
            {segment && series.map(item => <th key={item.label} scope="col" data-hidden={hidden.has(item.label) || undefined}>
              <span className="kbc-series-heading" title={item.label}><i className="kbc-swatch" style={{ background: item.color }} /><span dir="auto">{item.label}</span></span>
            </th>)}
          </tr></thead>
          <tbody onPointerLeave={() => setActive(null)}>{rows.map(row => <tr key={row.label} data-active={active === row.label || undefined}
            onPointerEnter={event => { if (event.pointerType !== "touch") setActive(row.label); }}>
            <th scope="row"><span className="kbc-row-label" title={row.label}>{slice?.icons?.[row.label]}<span dir="auto">{row.label}</span></span></th>
            <td className="kbc-sum">{format.format(row.total)}</td>
            {segment && series.map((item, i) => <td key={item.label} data-hidden={hidden.has(item.label) || undefined}>{format.format(row.values[i])}</td>)}
          </tr>)}</tbody>
        </table>
      </div>
    </div>
    <footer className="kbc-foot">
      {segment ? <div className="kbc-legend" role="group" aria-label={segment.label}>
        {series.map(item => <button className="kbc-chip" type="button" key={item.label} title={item.label}
          aria-pressed={!hidden.has(item.label)} onClick={() => toggleSeries(item.label)}>
          <i className="kbc-swatch" style={{ background: item.color }} /><span dir="auto">{item.label}</span>
        </button>)}
      </div> : <span className="kbc-empty-legend">Pick a segment to split the bars</span>}
      {hidden.size > 0 && <button type="button" className="kbc-reset" onClick={() => setExcluded(new Set())}>Show all</button>}
    </footer>
  </section>;
}

"use client";

import { useId, useRef, useState } from "react";
import { Select } from "@base-ui/react/select";

type BreakdownPickerProps = {
  label: string;
  value: string;
  options: readonly { key: string; label: string }[];
  onChange: (value: string) => void;
};

export function BreakdownPicker({ label, value, options, onChange }: BreakdownPickerProps) {
  const labelId = useId();
  const container = useRef<HTMLDivElement>(null);
  const returnFocus = useRef(true);
  const [navigating, setNavigating] = useState(false);
  const selected = options.find(option => option.key === value)?.label;

  return <div className="kbc-picker" ref={container}>
    <span className="kbc-picker-label" id={labelId}>{label}</span>
    <Select.Root<string>
      value={value}
      modal={false}
      disabled={!options.length}
      onValueChange={next => { if (next !== null) onChange(next); }}
      onOpenChange={(open, details) => {
        setNavigating(false);
        if (open) returnFocus.current = true;
        else if (details.reason === "outside-press" || details.reason === "focus-out") returnFocus.current = false;
      }}
    >
      <Select.Trigger className="kbc-trigger" aria-labelledby={labelId} title={selected}>
        <span dir="auto">{selected}</span>
        <svg aria-hidden="true" width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.1" strokeLinecap="round" strokeLinejoin="round">
          <path d="m4.5 6.25 3.5 3.5 3.5-3.5" />
        </svg>
      </Select.Trigger>
      <Select.Portal container={container} style={{ display: "contents" }}>
        <Select.Positioner className="kbc-positioner" align="start" sideOffset={4} alignItemWithTrigger={false} collisionAvoidance={{ side: "none", align: "shift" }}>
          <Select.Popup
            className="kbc-menu"
            data-navigating={navigating || undefined}
            finalFocus={() => returnFocus.current}
            onPointerMove={() => setNavigating(true)}
            onPointerLeave={() => setNavigating(false)}
            onKeyDownCapture={event => {
              if (["ArrowUp", "ArrowDown", "Home", "End"].includes(event.key) || event.key.length === 1) setNavigating(true);
            }}
          >
            <Select.List aria-labelledby={labelId}>
              {options.map(option => <Select.Item
                className="kbc-option"
                key={option.key}
                value={option.key}
                label={option.label}
              >
                <Select.ItemText dir="auto" title={option.label}>{option.label}</Select.ItemText>
                {option.key === value && <svg aria-hidden="true" width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" strokeLinejoin="round">
                  <path d="m3.5 8.5 3 3 6-7" />
                </svg>}
              </Select.Item>)}
            </Select.List>
          </Select.Popup>
        </Select.Positioner>
      </Select.Portal>
    </Select.Root>
  </div>;
}

"use client";

import { useId, useLayoutEffect, useRef, type CSSProperties, type ReactNode } from "react";

export interface BreakdownRow {
  label: string;
  total: number;
  values: number[];
}

export interface BreakdownSeries {
  label: string;
  color: string;
}

interface BreakdownPlotProps {
  rows: readonly BreakdownRow[];
  series: readonly BreakdownSeries[];
  slice: { icons?: Readonly<Record<string, ReactNode>> };
  isSegmented: boolean;
  hidden: ReadonlySet<string>;
  unit: string;
  active: string | null;
  onInspect: (label: string | null) => void;
}

const format = new Intl.NumberFormat("en-US", { maximumFractionDigits: 2 });
const divisions = [5, 4, 3, 2, 1, 0];

function tickInterval(maximum: number) {
  if (maximum <= 0) return 1;
  const unrounded = maximum / 5;
  const magnitude = 10 ** Math.floor(Math.log10(unrounded));
  const fraction = unrounded / magnitude;
  const increment = [1, 2, 2.5, 5, 10].find(step => step >= fraction) ?? 10;
  return increment * magnitude;
}

export function BreakdownPlot({ rows, series, slice, isSegmented, hidden, unit, active, onInspect }: BreakdownPlotProps) {
  const plot = useRef<HTMLDivElement>(null);
  const tooltip = useRef<HTMLDivElement>(null);
  const pill = useRef<HTMLSpanElement>(null);
  const tooltipId = useId();
  const activeIndex = rows.findIndex(row => row.label === active);
  const inspected = rows[activeIndex];
  const interval = tickInterval(rows.reduce((max, row) => Math.max(max, row.total), 0));
  const gridStyle = { gridTemplateColumns: `repeat(${Math.max(1, rows.length)}, minmax(0, 1fr))` };
  const entries = series.map((item, index) => ({ ...item, index })).filter(item => !hidden.has(item.label));
  const details = inspected && isSegmented
    ? entries.filter(item => inspected.values[item.index] > 0).sort((a, b) => inspected.values[b.index] - inspected.values[a.index])
    : [];

  // The plot can use the card's side gutters for its callout and active label.
  // Measure the overlays themselves so custom icons and long labels fit too.
  useLayoutEffect(() => {
    const area = plot.current;
    const card = tooltip.current;
    const badge = pill.current;
    const frame = area?.parentElement;
    if (!area || !card || !badge || !frame || activeIndex < 0) return;
    const position = () => {
      const width = area.clientWidth;
      const center = width * (activeIndex + 0.5) / rows.length;
      const gutter = area.getBoundingClientRect().left - frame.getBoundingClientRect().left;
      const leftEdge = 4 - gutter;
      const rightEdge = frame.clientWidth - gutter - 4;
      const right = activeIndex < rows.length / 2;
      const idealLeft = right ? center + 18 : center - 18 - card.offsetWidth;
      card.style.left = Math.max(leftEdge, Math.min(idealLeft, rightEdge - card.offsetWidth)) + "px";

      const halfBadge = badge.offsetWidth / 2;
      const badgeCenter = Math.max(leftEdge + halfBadge, Math.min(center, rightEdge - halfBadge));
      badge.style.marginLeft = (badgeCenter - center) + "px";
    };
    position();
    const observer = new ResizeObserver(position);
    observer.observe(area);
    observer.observe(card);
    observer.observe(badge);
    return () => observer.disconnect();
  }, [activeIndex, rows.length]);

  return (
    <div className="kbc-chart" onPointerLeave={() => onInspect(null)}>
      <div className="kbc-plot" ref={plot}>
        {divisions.map(tick => (
          <span className="kbc-gridline" key={tick} data-baseline={tick === 0 || undefined} style={{ bottom: `${tick * 20}%` }} aria-hidden="true">
            <span className="kbc-tick">{format.format(tick * interval)}</span>
          </span>
        ))}
        <div className="kbc-bars" style={gridStyle}>
          {/* Preserve physical stack positions so regrouping animates from the previous view. */}
          {rows.map((row, column) => {
            const height = `${Math.max(0, row.total / interval * 20)}%`;
            const selected = row.label === active;
            return (
              <button className="kbc-column" type="button" key={column}
                aria-label={`${row.label}: ${format.format(row.total)} ${unit}`}
                aria-describedby={selected ? tooltipId : undefined}
                data-active={selected || undefined}
                data-dim={!!inspected && !selected || undefined}
                style={{ "--kbc-fill-height": height } as CSSProperties}
                onPointerEnter={event => { if (event.pointerType !== "touch") onInspect(row.label); }}
                onClick={() => onInspect(row.label)}
                onFocus={() => onInspect(row.label)} onBlur={() => onInspect(null)}>
                <span aria-hidden="true" className="kbc-rest" />
                <span aria-hidden="true" className="kbc-stack">
                  {entries.map(({ color, index }) => row.values[index] > 0 && (
                    <span className="kbc-stack-part" key={index} style={{ flexGrow: row.values[index], backgroundColor: color }} />
                  ))}
                </span>
              </button>
            );
          })}
        </div>
        {inspected && (
          <div ref={tooltip} id={tooltipId} className="kbc-tooltip" role="status">
            <p className="kbc-tip-heading">
              <span className="kbc-tip-label">{slice.icons?.[inspected.label]}<span dir="auto">{inspected.label}</span></span>
              <strong>{format.format(inspected.total)}</strong>
            </p>
            {details.length > 0 && (
              <ul>
                {details.map(({ label, color, index }) => (
                  <li key={label}>
                    <i className="kbc-swatch" style={{ backgroundColor: color }} />
                    <span className="kbc-tip-series" dir="auto">{label}</span>
                    <span className="kbc-tip-number">{format.format(inspected.values[index])}</span>
                  </li>
                ))}
              </ul>
            )}
          </div>
        )}
      </div>
      <div className="kbc-xaxis" style={gridStyle} aria-hidden="true">
        {rows.map(({ label }, column) => (
          <span className="kbc-xlabel" key={column} title={label}
            onPointerEnter={event => { if (event.pointerType !== "touch") onInspect(label); }}>
            {active === label
              ? <span ref={pill} className="kbc-axis-pill">{slice.icons?.[label]}<span dir="auto">{label}</span></span>
              : slice.icons?.[label] ?? <span className="kbc-axis-text" dir="auto">{label}</span>}
          </span>
        ))}
      </div>
    </div>
  );
}

// Generated from the Breakdown Chart design tokens and styles.
export const breakdownPalette = ["var(--kbc-base-chart-1)","var(--kbc-base-chart-2)","var(--kbc-base-chart-3)","var(--kbc-base-chart-4)","var(--kbc-base-chart-5)"] as const;
export const breakdownChartStyleHref = "kalos-breakdown-chart-8577678d6678";
export const breakdownChartCss = ".kalos-breakdown-chart{--kbc-surface:#ffffff;--kbc-control:#ffffff;--kbc-popover:#ffffff;--kbc-strong:#000000;--kbc-ink:rgba(0, 0, 0, 0.88);--kbc-secondary:rgba(0, 0, 0, 0.61);--kbc-muted:rgba(0, 0, 0, 0.45);--kbc-grid:rgba(0, 0, 0, 0.06);--kbc-baseline:rgba(0, 0, 0, 0.12);--kbc-wash:rgba(0, 0, 0, 0.035);--kbc-hover:rgba(0, 0, 0, 0.03);--kbc-row-hover:#f7f7f7;--kbc-focus:rgba(0, 96, 226, 0.7);--kbc-check:rgba(0, 96, 226, 0.76);--kbc-shadow:0 0 0 0.5px rgba(0,0,0,.06), 0 1px 1px -1px rgba(0,0,0,.1), 0 1px 2px rgba(0,0,0,.05);--kbc-hover-shadow:0 0 0 0.5px rgba(0,0,0,.12), 0 1px 1px -1px rgba(0,0,0,.1), 0 1px 2px rgba(0,0,0,.05);--kbc-pop-shadow:0 0 0 0.5px rgba(0,0,0,.08), 0 12px 28px -10px rgba(0,0,0,.16), 0 1px 2px rgba(0,0,0,.05);--kbc-base-chart-1:var(--chart-series-1, #165dff);--kbc-base-chart-2:var(--chart-series-2, #3bb6ff);--kbc-base-chart-3:var(--chart-series-3, #7cdcf7);--kbc-base-chart-4:var(--chart-series-4, #5b63f6);--kbc-base-chart-5:var(--chart-series-5, #9270f5);--kbc-ease:cubic-bezier(0.22, 1, 0.36, 1);--kbc-width:560px;--kbc-radius:10px;--kbc-restack:520ms;--kbc-table-motion:380ms;font-family:Inter,Roboto, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", ByteSans, Arial, "Helvetica Neue", -apple-system, BlinkMacSystemFont, "noto sans", Helvetica, sans-serif}
:where(.dark,[data-theme=dark]) .kalos-breakdown-chart{--kbc-surface:#1c1c1e;--kbc-control:#232325;--kbc-popover:#252527;--kbc-strong:#ffffff;--kbc-ink:rgba(255, 255, 255, 0.9);--kbc-secondary:rgba(255, 255, 255, 0.62);--kbc-muted:rgba(255, 255, 255, 0.46);--kbc-grid:rgba(255, 255, 255, 0.08);--kbc-baseline:rgba(255, 255, 255, 0.16);--kbc-wash:rgba(255, 255, 255, 0.05);--kbc-hover:rgba(255, 255, 255, 0.04);--kbc-row-hover:#252527;--kbc-focus:rgba(77, 141, 255, 0.8);--kbc-check:#4d8dff;--kbc-shadow:0 0 0 0.5px rgba(255,255,255,.1), 0 1px 2px rgba(0,0,0,.4);--kbc-hover-shadow:0 0 0 0.5px rgba(255,255,255,.2), 0 1px 2px rgba(0,0,0,.4);--kbc-pop-shadow:0 0 0 0.5px rgba(255,255,255,.12), 0 12px 28px -10px rgba(0,0,0,.6);--kbc-base-chart-1:var(--chart-series-1, #2f6fef);--kbc-base-chart-2:var(--chart-series-2, #3bb6ff);--kbc-base-chart-3:var(--chart-series-3, #88e4ff);--kbc-base-chart-4:var(--chart-series-4, #5b63f6);--kbc-base-chart-5:var(--chart-series-5, #9270f5)}
.kalos-breakdown-chart {
  container: breakdown-chart / inline-size;
  position: relative;
  width: 100%;
  max-width: var(--kbc-width);
  min-width: 0;
  box-sizing: border-box;
  border-radius: var(--kbc-radius);
  background: var(--kbc-surface);
  box-shadow: var(--kbc-shadow);
  color: var(--kbc-ink);
  font-size: 13px;
  line-height: 20px;
  font-variant-numeric: tabular-nums;
  -webkit-font-smoothing: antialiased;
}
.kalos-breakdown-chart *, .kalos-breakdown-chart *::before, .kalos-breakdown-chart *::after { box-sizing: border-box; }
.kalos-breakdown-chart :where(button, [role=option]) {
  appearance: none;
  margin: 0;
  padding: 0;
  border: 0;
  background: none;
  font: inherit;
  color: inherit;
  cursor: pointer;
}
.kalos-breakdown-chart button:focus-visible { outline: 2px solid var(--kbc-focus); outline-offset: 2px; }
.kalos-breakdown-chart svg { display: block; flex-shrink: 0; }
.kbc-head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 12px; padding: 14px 16px 0; }
.kbc-head .kbc-title { flex: 1; min-width: min(120px, 100%); margin: 0; color: var(--kbc-strong); font-size: 15px; font-weight: 500; line-height: 24px; }
.kbc-title, .kbc-trigger > span, .kbc-option > span, .kbc-chip > span, .kbc-series-heading > span, .kbc-row-label > span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.kbc-total { max-width: 100%; color: var(--kbc-muted); font-size: 12px; line-height: 16px; font-variant-numeric: tabular-nums; }
.kbc-total strong { color: var(--kbc-ink); font-size: 15px; font-weight: 500; line-height: 24px; }
.kbc-controls { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; padding: 12px 16px 0; }
.kbc-picker { display: flex; flex-direction: column; min-width: 0; gap: 4px; }
.kbc-picker-label { padding-left: 2px; font-size: 12px; line-height: 16px; color: var(--kbc-muted); }
.kbc-trigger {
  display: flex; align-items: center; justify-content: space-between; gap: 6px;
  width: 100%; height: 28px; padding: 0 6px 0 10px;
  background: var(--kbc-control); box-shadow: var(--kbc-shadow); border-radius: 6px;
  color: var(--kbc-strong); font-weight: 500; text-align: left;
  transition: box-shadow 160ms;
}
.kbc-trigger:hover, .kbc-trigger[aria-expanded=true] { box-shadow: var(--kbc-hover-shadow); }
.kbc-trigger svg { color: var(--kbc-muted); transition: transform 220ms var(--kbc-ease); }
.kbc-trigger[aria-expanded=true] svg { transform: rotate(180deg); }
.kbc-positioner { z-index: 6; width: max(140px, var(--anchor-width)); max-width: var(--available-width); outline: none; }
.kbc-menu {
  border-radius: 10px; padding: 4px; background: var(--kbc-popover); box-shadow: var(--kbc-pop-shadow);
  overflow-y: auto; max-height: min(320px, var(--available-height)); outline: none;
  transform-origin: var(--transform-origin); animation: kbc-menu-in 180ms var(--kbc-ease);
}
.kbc-menu[data-ending-style], .kbc-menu[data-closed] { animation: none; opacity: 0; pointer-events: none; }
@keyframes kbc-menu-in { from { opacity: 0; transform: translateY(-4px) scale(.98); } to { opacity: 1; transform: none; } }
.kbc-option { display: flex; align-items: center; justify-content: space-between; gap: 8px; height: 28px; padding: 0 6px 0 8px; border-radius: 6px; outline: none; }
.kbc-menu[data-navigating] .kbc-option[data-highlighted] { background: var(--kbc-grid); }
.kbc-option svg { color: var(--kbc-check); }
.kbc-table-frame { overflow: hidden; transition: height var(--kbc-table-motion) var(--kbc-ease); }
.kbc-table-scroll { overflow: auto; scrollbar-width: none; border-top: 1px solid var(--kbc-grid); }
.kbc-table-scroll::-webkit-scrollbar, .kbc-legend::-webkit-scrollbar { display: none; }
.kbc-table {
  width: 100%; border-collapse: collapse; border-spacing: 0; font-size: 13px;
  line-height: 20px; font-variant-numeric: tabular-nums;
}
.kbc-table :is(td, th) { padding: 0 10px; background: var(--kbc-surface); text-align: right; white-space: nowrap; }
.kbc-table :is(td, th):first-child { padding-left: 16px; text-align: left; }
.kbc-table :is(td, th):last-child { padding-right: 16px; }
.kbc-table thead th { height: 32px; color: var(--kbc-muted); font-size: 10px; font-weight: 500; line-height: 16px; letter-spacing: .5px; text-transform: uppercase; }
.kbc-table tbody :is(th,td) { height: 36px; border-top: 1px solid var(--kbc-grid); font-weight: 400; }
.kbc-table tbody th { position: sticky; left: 0; z-index: 1; }
.kbc-table tbody td { color: var(--kbc-secondary); }
.kbc-table tbody .kbc-sum { color: var(--kbc-ink); }
.kbc-table tr[data-active] > * { background: var(--kbc-row-hover); }
.kbc-table [data-hidden] { opacity: .35; }
.kbc-series-heading, .kbc-row-label { display: inline-flex; align-items: center; }
.kbc-series-heading { gap: 6px; max-width: 160px; }
.kbc-row-label { gap: 8px; max-width: 220px; }
.kbc-row-label > :where(svg, img) { width: 16px; height: 16px; flex-shrink: 0; }
.kbc-swatch { display: inline-block; flex: 0 0 8px; width: 8px; height: 8px; border-radius: 2px; }
.kbc-foot { display: flex; align-items: center; justify-content: space-between; gap: 8px; min-height: 44px; border-top: 1px solid var(--kbc-grid); padding: 8px; }
.kbc-legend { display: flex; align-items: center; gap: 2px; overflow-x: auto; min-width: 0; scrollbar-width: none; }
.kbc-chip, .kbc-reset { flex: none; display: inline-flex; align-items: center; justify-content: center; height: 28px; border-radius: 6px; white-space: nowrap; }
.kbc-chip { gap: 6px; max-width: 220px; padding: 0 8px; color: var(--kbc-secondary); font-size: 12px; font-weight: 500; line-height: 16px; transition: background-color 140ms, color 140ms, opacity 160ms; }
.kbc-chip:hover, .kbc-reset:hover { background: var(--kbc-hover); color: var(--kbc-ink); }
.kbc-chip[aria-pressed=false] { opacity: .45; text-decoration: line-through; }
.kbc-reset { padding: 0 10px; font-weight: 500; transition: background-color 140ms; }
.kbc-chip:focus-visible { outline-offset: -2px !important; }
.kbc-empty-legend { padding-left: 8px; font-size: 12px; line-height: 16px; color: var(--kbc-muted); }
@container breakdown-chart (max-width: 420px) {
  .kbc-head { padding: 12px 12px 0; }
  .kbc-controls { padding: 10px 12px 0; gap: 6px; }
  .kbc-trigger { padding-inline: 8px 4px; }
  .kbc-foot { padding: 6px; }
  .kbc-legend { gap: 0; }
  .kbc-chip { gap: 5px; padding-inline: 6px; }
  .kbc-table :is(td, th):first-child { padding-left: 12px; }
  .kbc-table :is(td, th):last-child { padding-right: 12px; }
}

.kbc-chart {
  padding: 20px 16px 10px;
  --kbc-bar-width: 12px;
}

.kbc-plot {
  position: relative;
  height: 196px;
  margin-right: 28px;
}

.kbc-gridline {
  position: absolute;
  right: 0;
  left: 0;
  border-top: 1px solid var(--kbc-grid);
  pointer-events: none;
}

.kbc-gridline[data-baseline] { border-color: var(--kbc-baseline); }

.kbc-tick {
  position: absolute;
  top: -8px;
  right: -28px;
  width: 24px;
  color: var(--kbc-muted);
  font-size: 11px;
  line-height: 16px;
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.kbc-bars,
.kbc-xaxis {
  display: grid;
  min-width: 0;
  gap: 4px;
}

.kbc-bars { position: absolute; inset: 0; }

.kalos-breakdown-chart .kbc-column {
  position: relative;
  display: flex;
  min-width: 0;
  align-items: flex-end;
  justify-content: center;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: inherit;
  cursor: pointer;
  transition: opacity 200ms ease;
}

.kbc-column:focus-visible { outline: 2px solid var(--kbc-focus); outline-offset: 2px; }
.kbc-column[data-dim] { opacity: 0.35; }

.kbc-stack,
.kbc-rest {
  width: var(--kbc-bar-width);
  max-width: 100%;
  border-radius: 3px 3px 0 0;
  pointer-events: none;
}

.kbc-stack {
  position: relative;
  display: flex;
  height: var(--kbc-fill-height);
  flex-direction: column-reverse;
  gap: 1px;
  overflow: hidden;
  transition: height var(--kbc-restack) var(--kbc-ease);
}

.kbc-stack-part {
  display: block;
  min-height: 0;
  flex-basis: 0;
  transition: flex-grow var(--kbc-restack) var(--kbc-ease), background-color 300ms ease;
}

.kbc-rest {
  position: absolute;
  top: 0;
  bottom: var(--kbc-fill-height);
  left: 50%;
  transform: translateX(-50%);
  background: var(--kbc-wash);
  opacity: 0;
  transition: opacity 180ms ease, bottom var(--kbc-restack) var(--kbc-ease);
}

.kbc-column[data-active] .kbc-rest { opacity: 1; }

.kbc-xaxis { margin: 8px 28px 0 0; }

.kbc-xlabel {
  position: relative;
  display: grid;
  height: 24px;
  min-width: 0;
  place-items: center;
  color: var(--kbc-muted);
}

.kbc-axis-text,
.kbc-axis-pill > span,
.kbc-tip-label > span,
.kbc-tip-series {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.kbc-axis-text {
  max-width: 100%;
  font-size: 11px;
  line-height: 16px;
}

.kbc-axis-pill {
  position: absolute;
  z-index: 2;
  top: 50%;
  left: 50%;
  display: flex;
  width: max-content;
  max-width: min(220px, 80cqi);
  height: 24px;
  align-items: center;
  gap: 6px;
  padding: 0 8px 0 6px;
  border-radius: 6px;
  transform: translate(-50%, -50%);
  background: var(--kbc-surface);
  box-shadow: var(--kbc-shadow);
  color: var(--kbc-ink);
  font-size: 12px;
  font-weight: 500;
  line-height: 16px;
  animation: kbc-axis-pill-in 200ms var(--kbc-ease);
}

@keyframes kbc-axis-pill-in {
  from { transform: translate(-50%, -50%) scale(.92); opacity: 0; }
  to { transform: translate(-50%, -50%); opacity: 1; }
}

.kbc-tooltip {
  position: absolute;
  z-index: 4;
  top: 0;
  width: max-content;
  min-width: min(152px, 100%);
  max-width: min(260px, 100%);
  padding: 6px 10px 8px;
  border-radius: 10px;
  background: var(--kbc-popover);
  box-shadow: var(--kbc-pop-shadow);
  color: var(--kbc-ink);
  font-variant-numeric: tabular-nums;
  pointer-events: none;
  transition: left 200ms var(--kbc-ease);
  animation: kbc-tooltip-in 160ms var(--kbc-ease);
}

@keyframes kbc-tooltip-in { from { opacity: 0; } to { opacity: 1; } }

.kbc-tip-heading,
.kbc-tip-label,
.kbc-tooltip li {
  display: flex;
  align-items: center;
}

.kalos-breakdown-chart .kbc-tip-heading {
  min-width: 0;
  justify-content: space-between;
  gap: 16px;
  margin: 0;
  padding: 0;
  color: var(--kbc-strong);
  font-size: 13px;
  font-weight: 500;
  line-height: 20px;
}

.kbc-tip-label { min-width: 0; gap: 6px; }
.kbc-tip-label > svg, .kbc-axis-pill > svg { flex-shrink: 0; }
.kbc-tip-heading strong { font-weight: 500; }

.kalos-breakdown-chart .kbc-tooltip ul {
  display: grid;
  gap: 0;
  margin: 4px 0 0;
  padding: 4px 0 0;
  border-top: 1px solid var(--kbc-grid);
  list-style: none;
}

.kalos-breakdown-chart .kbc-tooltip li {
  min-width: 0;
  gap: 8px;
  margin: 0;
  padding: 0;
  color: var(--kbc-secondary);
  font-size: 12px;
  line-height: 20px;
}

.kbc-tip-series { flex: 1; }
.kbc-tip-number { color: var(--kbc-ink); }

@container breakdown-chart (max-width: 420px) {
  .kbc-chart { padding: 18px 12px 8px; --kbc-bar-width: 10px; }
  .kbc-plot { height: 168px; }
